-- Two-house price block on every item tooltip (SPEC D-042 to D-046). Data: ns.PRICES from Data/Prices.lua (generated by
-- `wowf-analysis export-addon`, gitignored). One packed string per item, decoded on first hover and cached (D-043).
-- Pure except Prices.Context (reads the tooltip's stack count) and the slash/status helpers.
local _, ns = ...
local L = ns.L

local type, tonumber, ipairs, pairs, floor, abs, max, format, concat, pcall =
  type, tonumber, ipairs, pairs, math.floor, math.abs, math.max, string.format, table.concat, pcall

local Prices = {}
ns.Prices = Prices

Prices.HAUL_MIN = 0.10 -- haul line threshold: net per unit at least 10% of the floor where you buy (D-045)
Prices.THIN = 5 -- fewer inferred sales than this: the headline says "thin" (D-046)
Prices.STALE = 86400 -- listing data older than this shows its age in short mode too
Prices.MODES = { "full", "short", "off" }
local FIELDS = { "floor", "median", "units", "cheap", "sells", "n", "perDay10", "trend", "sellsDays" } -- SPEC D-043 order

local HOUSE_COLORS = { [111] = "ff4080ff", [114] = "ffe04848", [117] = "ff40c8d0" }
local GREY, GREEN, RED, YELLOW, ORANGE = "ffa0a0a0", "ff40e060", "ffff5050", "ffffd200", "ffffa030"
local function C(color, text) return "|c" .. color .. text .. "|r" end

function Prices.Get() return ns.PRICES end

----------------------------------------------------------------------------------------------------
-- Decoding
----------------------------------------------------------------------------------------------------
local function Split(s, sep)
  local out, i = {}, 1
  while true do
    local j = s:find(sep, i, true)
    if not j then out[#out + 1] = s:sub(i) return out end
    out[#out + 1] = s:sub(i, j - 1)
    i = j + 1
  end
end

local cache, cacheOf = {}, nil
-- { [house] = { floor =, median =, units =, cheap =, sells =, n =, perDay10 =, trend =, sellsDays = } } or nil.
-- A house with an empty or malformed part is absent; a malformed field is nil.
function Prices.Decode(id)
  local P = Prices.Get()
  if not (P and type(P.items) == "table" and type(P.houses) == "table") then return nil end
  if cacheOf ~= P then cache, cacheOf = {}, P end
  local hit = cache[id]
  if hit ~= nil then return hit or nil end
  local s, out = P.items[id], false
  if type(s) == "string" then
    out = {}
    for i, part in ipairs(Split(s, ";")) do
      local h = P.houses[i]
      if h and part ~= "" then
        local d, any = {}, false
        for k, v in ipairs(Split(part, ",")) do
          local name = FIELDS[k]
          if name then
            d[name] = tonumber(v)
            if d[name] then any = true end
          end
        end
        if any then out[h] = d end
      end
    end
    if next(out) == nil then out = false end
  end
  cache[id] = out
  return out or nil
end

----------------------------------------------------------------------------------------------------
-- Formatting
----------------------------------------------------------------------------------------------------
-- Compact money: copper dropped from 1g up ("12g 50s"), otherwise Plan.Money.
function Prices.Money(c)
  if type(c) ~= "number" then return "?" end
  c = floor(c + 0.5)
  if c >= 10000 then
    local g, s = floor(c / 10000), floor((c % 10000) / 100 + 0.5)
    if s == 100 then g, s = g + 1, 0 end
    return s > 0 and format("%dg %ds", g, s) or format("%dg", g)
  end
  return ns.Plan.Money(c)
end

function Prices.Units(n)
  if type(n) ~= "number" then return "?" end
  if n >= 1000000 then return format("%.1fM", n / 1000000) end
  if n >= 10000 then return format("%.1fk", n / 1000) end
  return tostring(floor(n))
end

function Prices.PerDay(p10)
  if type(p10) ~= "number" then return nil end
  local v = p10 / 10
  if v >= 10000 then return Prices.Units(v) .. "/d" end
  if v >= 10 or v == 0 then return floor(v + 0.5) .. "/d" end
  return format("%.1f/d", v)
end

function Prices.Trend(t)
  if type(t) ~= "number" then return nil end
  if abs(t) < 2 then return C(GREY, "7d flat") end
  return C(t < 0 and RED or GREEN, format("7d %+d%%", t))
end

-- Houses in display order: the house you stand at first, then the export's order (D-044).
function Prices.Order(house)
  local P = Prices.Get()
  local out = {}
  if not (P and P.houses) then return out end
  for _, h in ipairs(P.houses) do if h == house then out[1] = h end end
  for _, h in ipairs(P.houses) do if h ~= out[1] then out[#out + 1] = h end end
  return out
end

local function Cut(h) return (ns.Post.Cut(h)) end
local function Net(d, h) return d and d.sells and d.sells * (1 - Cut(h)) or nil end

local function Ago(iso, now)
  local t = ns.Plan.ParseTime(iso)
  if not t then return nil end
  return max(0, now - t)
end

-- Pure. opts = { mode = "full"|"short", house =, confident =, count = stack count or nil, vendorUnit = copper or nil,
-- now = server time }. Returns a list of { left, right } (right nil = single line), or nil when there is nothing to show.
function Prices.Lines(id, opts)
  local mode = opts.mode or "full"
  if mode == "off" then return nil end
  local dec = Prices.Decode(id)
  if not dec then return nil end
  local P, Plan = Prices.Get(), ns.Plan
  local full = mode == "full"
  local win = (P.window or 7) .. "d"
  local order = Prices.Order(opts.house)
  local rows = {}

  for i, h in ipairs(order) do
    local d = dec[h]
    local name = Plan.HouseName(h)
    local left = C(HOUSE_COLORS[h] or "ffffffff", name)
    if i == 1 and h == opts.house and opts.confident then left = left .. C(GREY, " (here)") end
    if not d then
      rows[#rows + 1] = { left, C(GREY, L["no data"]) }
    else
      local parts = {}
      if d.sells then
        parts[1] = L["sells"] .. " " .. Prices.Money(d.sells) .. ((d.n or 0) < Prices.THIN and C(ORANGE, " " .. L["thin"]) or "")
      else
        parts[1] = C(GREY, format(L["no sales %s"], win))
      end
      parts[2] = d.floor and (L["floor"] .. " " .. Prices.Money(d.floor)) or C(GREY, L["none listed"])
      local pd = Prices.PerDay(d.perDay10)
      if pd then parts[3] = pd end
      rows[#rows + 1] = { left, concat(parts, " · ") }
      if full then
        local det = {}
        if d.median then det[#det + 1] = L["median"] .. " " .. Prices.Money(d.median) end
        det[#det + 1] = format(L["%s listed"], Prices.Units(d.units or 0))
          .. ((d.cheap and d.cheap > 0) and format(L[", %s near floor"], Prices.Units(d.cheap)) or "")
        local tr = Prices.Trend(d.trend)
        if tr then det[#det + 1] = tr end
        if d.n then
          det[#det + 1] = format(d.n == 1 and L["%d sale"] or L["%d sales"], d.n)
            .. (d.sellsDays and format(" (%dd)", d.sellsDays) or "")
        end
        rows[#rows + 1] = { "   " .. C(GREY, concat(det, C(GREY, " · "))) }
      end
    end
  end

  -- Haul: buy at the floor of the top house, sell at the other house's median sale, net of its cut (D-045).
  local a, b = order[1], order[2]
  local da, db = a and dec[a], b and dec[b]
  if da and da.floor and da.floor > 0 and db and db.sells then
    local net = Net(db, b) - da.floor
    if net >= 1 and net >= Prices.HAUL_MIN * da.floor then
      rows[#rows + 1] = { C(GREEN, format(L["Haul → %s: +%s/u net of %d%% cut (+%d%%)"], Plan.HouseName(b),
        Prices.Money(net), floor(Cut(b) * 100 + 0.5), floor(100 * net / da.floor + 0.5))) }
    end
  end

  -- Vendor flags need a per-unit vendor value from the tooltip's own sell price line (P-011).
  local vu = opts.vendorUnit
  if vu and vu > 0 then
    if da and da.floor and da.floor < vu then
      rows[#rows + 1] = { C(YELLOW, format(L["Vendor flip: floor %s < vendor %s"], Prices.Money(da.floor), Prices.Money(vu))) }
    end
    local best
    for _, h in ipairs(order) do
      local n = Net(dec[h], h)
      if n and (not best or n > best) then best = n end
    end
    if best and vu >= best then
      rows[#rows + 1] = { C(YELLOW, format(L["Vendor %s beats the AH (best net %s)"], Prices.Money(vu), Prices.Money(best))) }
    end
  end

  if full and opts.count and opts.count > 1 then
    local st = {}
    for _, h in ipairs(order) do
      local n = Net(dec[h], h)
      if n then st[#st + 1] = Prices.Money(n * opts.count) .. " " .. Plan.HouseName(h) end
    end
    if #st > 0 then
      rows[#rows + 1] = { C(GREY, format(L["Stack x%d: %s (net of cut)"], opts.count, concat(st, " · "))) }
    end
  end

  local now = opts.now or 0
  local lAge = a and P.snap and Ago(P.snap[a], now)
  local sAge = a and P.sales and Ago(P.sales[a], now)
  local stale = lAge and lAge > Prices.STALE
  if full or stale then
    local txt = format(L["Prices: listings %s old · sales %s old"], lAge and Plan.AgeText(lAge) or "?",
      sAge and Plan.AgeText(sAge) or "?")
    rows[#rows + 1] = { C(stale and ORANGE or GREY, txt) }
  end
  return rows
end

----------------------------------------------------------------------------------------------------
-- Tooltip context (impure): stack count and per-unit vendor value from the tooltip data (D-045)
----------------------------------------------------------------------------------------------------
local function Secret(v) return issecretvalue ~= nil and issecretvalue(v) end

-- Returns count (nil when unknown), vendorUnit (nil when unknown).
function Prices.Context(data)
  if type(data) ~= "table" then return nil, nil end
  local sellType = Enum and Enum.TooltipDataLineType and Enum.TooltipDataLineType.SellPrice or 11
  local total
  if type(data.lines) == "table" then
    for _, line in ipairs(data.lines) do
      if type(line) == "table" and line.type == sellType and type(line.price) == "number" and not Secret(line.price) then
        total = line.price
      end
    end
  end
  local count
  local guid = data.guid
  if guid == nil then
    count = 1 -- a link tooltip (chat, vendor, loot): one unit
  elseif not Secret(guid) and C_Item and C_Item.GetItemLocation and C_Item.GetStackCount then
    local ok, loc = pcall(C_Item.GetItemLocation, guid)
    if ok and loc then
      local ok2, n = pcall(C_Item.GetStackCount, loc)
      if ok2 and type(n) == "number" and not Secret(n) and n > 0 then count = n end
    end
  end
  local vendorUnit = (total and count) and total / count or nil
  return count, vendorUnit
end

----------------------------------------------------------------------------------------------------
-- Settings: WuweiDB.prices = "full" (default) | "short" | "off"; /wuwei prices [full|short|off]
----------------------------------------------------------------------------------------------------
function Prices.Mode()
  local m = ns.db and ns.db.prices
  for _, v in ipairs(Prices.MODES) do if m == v then return m end end
  return "full"
end

function Prices.Count()
  local P, n = Prices.Get(), 0
  if P and type(P.items) == "table" then for _ in pairs(P.items) do n = n + 1 end end
  return n
end

function Prices.StatusLine()
  local P = Prices.Get()
  if not P then return format(L["prices: %s · no Data/Prices.lua (run wowf-analysis export-addon, then /reload)"], Prices.Mode()) end
  local h = Prices.Order(ns.House.Detect())[1]
  local age = h and P.snap and Ago(P.snap[h], GetServerTime())
  return format(L["prices: %s · %d items · listings %s old"], Prices.Mode(), Prices.Count(),
    age and ns.Plan.AgeText(age) or "?")
end

function Prices.Slash(arg)
  arg = (arg or ""):lower()
  local set
  for _, v in ipairs(Prices.MODES) do if arg == v then set = v end end
  if not set then
    if arg ~= "" then return false end
    local cur = Prices.Mode()
    for i, v in ipairs(Prices.MODES) do if v == cur then set = Prices.MODES[i % #Prices.MODES + 1] end end
  end
  ns.db.prices = set
  return true
end
